"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io

# Quantity column used to be "available"; the supplier has renamed it.
# Identify it as the non-meta field (meta: sku, updated_at) so a further
# rename does not break nightly contract tests.
_META_COLUMNS = frozenset({"sku", "updated_at"})


def parse_feed(text):
    rows = csv.DictReader(io.StringIO(text))
    stock = {}
    for row in rows:
        sku = (row.get("sku") or "").strip()
        qty = None
        if "available" in row and row["available"] not in (None, ""):
            qty = int(row["available"])
        else:
            for key, val in row.items():
                if key in _META_COLUMNS or key is None or val in (None, ""):
                    continue
                try:
                    qty = int(val)
                    break
                except (TypeError, ValueError):
                    continue
        if not sku or qty is None:
            continue
        stock[sku] = qty
    return stock

