"""Bookable slots from the clinic's opening hours."""
import locale
from datetime import datetime, time, timedelta

SLOT_MINUTES = 30
SLOT_LENGTH = timedelta(minutes=SLOT_MINUTES)

OPENING_HOURS = {
    "monday": (time(8, 30), time(18, 0)),
    "tuesday": (time(8, 30), time(18, 0)),
    "wednesday": (time(8, 30), time(18, 0)),
    "thursday": (time(8, 30), time(18, 0)),
    "friday": (time(8, 30), time(14, 0)),
}


def _weekday_name(day):
    """English lowercase weekday, independent of LC_TIME on the build agent."""
    try:
        old = locale.setlocale(locale.LC_TIME)
    except locale.Error:
        return day.strftime("%A").lower()
    try:
        locale.setlocale(locale.LC_TIME, "C")
        return day.strftime("%A").lower()
    except locale.Error:
        return day.strftime("%A").lower()
    finally:
        try:
            locale.setlocale(locale.LC_TIME, old)
        except locale.Error:
            pass


def slots_for(day):
    hours = OPENING_HOURS.get(_weekday_name(day))
    if hours is None:
        return []
    start, end = (datetime.combine(day, t) for t in hours)
    slots = []
    while start + SLOT_LENGTH <= end:
        slots.append(start)
        start += SLOT_LENGTH
    return slots

